mkdir -p cmd/csvstat internal/cli internal/csvdata internal/profile internal/freq bin && \
printf 'module csvstat\n\ngo 1.22\n' > go.mod && \
cat > cmd/csvstat/main.go <<'EOF'
// Command csvstat profiles the columns of a CSV file.
package main

import (
	"os"

	"csvstat/internal/cli"
)

func main() {
	os.Exit(cli.Run(os.Args[1:], os.Stdout, os.Stderr))
}
EOF
cat > internal/cli/doc.go <<'EOF'
// Package cli parses arguments, dispatches commands, maps failures to exit
// codes, and writes diagnostics to standard error.
package cli
EOF
cat > internal/cli/cli.go <<'EOF'
package cli

import (
	"fmt"
	"io"
)

// Run executes csvstat with args, which excludes the program name, and returns
// the process exit code. Only cmd/csvstat calls os.Exit with this value.
func Run(args []string, stdout, stderr io.Writer) int {
	_ = stdout
	fmt.Fprintln(stderr, "csvstat: not implemented")
	return 1
}
EOF
cat > internal/csvdata/doc.go <<'EOF'
// Package csvdata reads CSV input, trims fields, recognizes null spellings, and
// rejects malformed input.
package csvdata
EOF
cat > internal/profile/doc.go <<'EOF'
// Package profile infers column types and computes counts, extremes, sums,
// means, and medians with exact arithmetic.
package profile
EOF
cat > internal/freq/doc.go <<'EOF'
// Package freq counts, orders, and limits column value frequencies.
package freq
EOF
cat > bin/test.sh <<'EOF'
#!/bin/sh
# Test gate: vet, then run the Go test suite. Exits non-zero on any failure.
set -eu
cd "$(dirname "$0")/.."
go vet ./...
go test ./...
EOF
chmod +x bin/test.sh && gofmt -l . ; sh bin/test.sh; echo "test exit=$?"; go build -o /tmp/csvstat_check ./cmd/csvstat && echo built; /tmp/csvstat_check; echo "run exit=$?"

